/**
 * Tab 'Categories' expand/close effect.
 */

const childPrefix = 'l_';
const parentPrefix = 'h_';

export function categoryCollapse() {
  document.addEventListener('hide.bs.collapse', updateCategory);
  document.addEventListener('show.bs.collapse', updateCategory);
}

function updateCategory(event) {
  const elem = event.target;

  if (!elem.id.startsWith(childPrefix)) {
    return;
  }

  const parentId = parentPrefix + elem.id.substring(childPrefix.length);
  const parent = document.getElementById(parentId);

  if (!parent) {
    return;
  }

  const isExpanded = event.type === 'show.bs.collapse';
  const folder = parent.querySelector(
    isExpanded ? '.far.fa-folder' : '.far.fa-folder-open'
  );
  const arrow = parent.querySelector('.fas.fa-angle-down');

  if (folder) {
    folder.className = isExpanded
      ? 'far fa-folder-open fa-fw'
      : 'far fa-folder fa-fw';
  }

  if (arrow) {
    arrow.classList.toggle('rotate', !isExpanded);
  }

  parent.classList.toggle('hide-border-bottom', isExpanded);
}
